import {FormEvent,useMemo,useState} from 'react'
import {CarFront,Save,X} from 'lucide-react'
import {saveVehicle} from '../lib/api'
import {VEHICLE_STATUSES,validateVehicleDraft} from '../domain/garage'
import type {Vehicle,VehicleDraft} from '../types'

type FormState={brand:string;model:string;version:string;plate:string;vin:string;first_registration:string;year:string;mileage:string;origin_country:string;status:string;asking_price:string;notes:string}
const fromVehicle=(v?:Vehicle):FormState=>({brand:v?.brand||'',model:v?.model||'',version:v?.version||'',plate:v?.plate||'',vin:v?.vin||'',first_registration:v?.first_registration||'',year:v?.year?String(v.year):'',mileage:v?.mileage===0?'0':v?.mileage?String(v.mileage):'',origin_country:v?.origin_country||'',status:v?.status||'IN_ARRIVO',asking_price:v?.asking_price?String(v.asking_price):'',notes:v?.notes||''})

export function VehicleFormModal({vehicle,onClose,onSaved}:{vehicle?:Vehicle;onClose:()=>void;onSaved:(vehicle:Vehicle)=>void}){
  const [form,setForm]=useState<FormState>(()=>fromVehicle(vehicle));const [busy,setBusy]=useState(false);const [error,setError]=useState('')
  const draft=useMemo<Partial<VehicleDraft>>(()=>({...form,year:form.year===''?null:Number(form.year),mileage:form.mileage===''?null:Number(form.mileage),asking_price:form.asking_price===''?null:Number(form.asking_price)}),[form])
  const validation=validateVehicleDraft(draft)
  const set=(key:keyof FormState,value:string)=>setForm(prev=>({...prev,[key]:value}))
  async function submit(e:FormEvent){e.preventDefault();if(!validation.valid){setError(validation.errors[0]);return}setBusy(true);setError('');try{onSaved(await saveVehicle(validation.value,vehicle?.id))}catch(err){setError(err instanceof Error?err.message:'Salvataggio non riuscito')}finally{setBusy(false)}}
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.currentTarget===e.target)onClose()}}><section className="vehicle-modal" role="dialog" aria-modal="true" aria-label={vehicle?'Modifica auto':'Nuova auto'}><header><div className="garage-modal-icon"><CarFront/></div><div><p className="eyebrow">GARAGE V2</p><h2>{vehicle?'Modifica auto':'Nuova auto'}</h2><p>{vehicle?'Aggiorna solo quello che serve.':'Inserisci i dati essenziali, le foto arrivano subito dopo.'}</p></div><button type="button" className="icon-btn" onClick={onClose} aria-label="Chiudi"><X/></button></header><form onSubmit={submit} className="vehicle-form"><div className="form-grid"><label>MARCA<input data-testid="vehicle-brand" autoFocus value={form.brand} onChange={e=>set('brand',e.target.value)} placeholder="es. Peugeot" required/></label><label>MODELLO<input data-testid="vehicle-model" value={form.model} onChange={e=>set('model',e.target.value)} placeholder="es. 308" required/></label><label className="span-2">VERSIONE<input value={form.version} onChange={e=>set('version',e.target.value)} placeholder="es. 1.5 BlueHDi Allure"/></label><label>TARGA<input value={form.plate} onChange={e=>set('plate',e.target.value.toUpperCase())} placeholder="AB123CD" autoCapitalize="characters"/></label><label>TELAIO / VIN<input value={form.vin} onChange={e=>set('vin',e.target.value.toUpperCase())} placeholder="VF3…" autoCapitalize="characters"/></label><label>PRIMA IMMATRICOLAZIONE<input type="date" value={form.first_registration} onChange={e=>set('first_registration',e.target.value)}/></label><label>ANNO<input inputMode="numeric" type="number" min="1950" max={new Date().getFullYear()+1} value={form.year} onChange={e=>set('year',e.target.value)} placeholder="2022"/></label><label>CHILOMETRI<input inputMode="numeric" type="number" min="0" step="1" value={form.mileage} onChange={e=>set('mileage',e.target.value)} placeholder="58000"/></label><label>PAESE ORIGINE<input value={form.origin_country} onChange={e=>set('origin_country',e.target.value.toUpperCase())} placeholder="IT" maxLength={3}/></label><label>STATO<select value={form.status} onChange={e=>set('status',e.target.value)}>{VEHICLE_STATUSES.map(s=><option key={s} value={s}>{s.replaceAll('_',' ')}</option>)}</select></label><label>PREZZO CLIENTE<input inputMode="decimal" type="number" min="0" step="50" value={form.asking_price} onChange={e=>set('asking_price',e.target.value)} placeholder="19900"/></label><label className="span-2">NOTE<textarea value={form.notes} onChange={e=>set('notes',e.target.value)} placeholder="Note operative visibili al team" rows={3}/></label></div>{error&&<div className="form-error">{error}</div>}<footer><button type="button" className="secondary-btn" onClick={onClose}>Annulla</button><button data-testid="vehicle-save" className="primary garage-save" disabled={busy||!validation.valid}><Save/>{busy?'Salvataggio…':vehicle?'Salva modifiche':'Crea auto'}</button></footer></form></section></div>}
