import {useCallback,useEffect,useState} from 'react'
import {RefreshCw} from 'lucide-react'
import {Login} from './components/Login'
import {Shell} from './components/Shell'
import {VehicleDrawer} from './components/VehicleDrawer'
import {VehicleFormModal} from './components/VehicleFormModal'
import {CalendarPage} from './pages/CalendarPage'
import {ClientsPage} from './pages/ClientsPage'
import {GaragePage} from './pages/GaragePage'
import {MorePage} from './pages/MorePage'
import {SalesPage} from './pages/SalesPage'
import {TodayPage} from './pages/TodayPage'
import {canWriteCalendar,canWriteCustomers,canWriteGarage,fetchTenantData,getSession,logout} from './lib/api'
import type {SessionPayload,TenantData,Vehicle,View} from './types'
const empty:TenantData={vehicles:[],media:[],workItems:[],customers:[],customerInteractions:[],customerInterests:[],calendarEvents:[],contracts:[],financials:[],costs:[],invoices:[]}
export default function App(){const [session,setSessionState]=useState<SessionPayload|null>(()=>getSession());const [view,setView]=useState<View>('today');const [data,setData]=useState<TenantData>(empty);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [vehicleId,setVehicleId]=useState<string|null>(null);const [newVehicleOpen,setNewVehicleOpen]=useState(false);const [editingId,setEditingId]=useState<string|null>(null);const load=useCallback(async()=>{if(!session)return;setBusy(true);setError('');try{setData(await fetchTenantData(session))}catch(err){setError(err instanceof Error?err.message:'Errore caricamento dati')}finally{setBusy(false)}},[session]);useEffect(()=>{void load()},[load]);useEffect(()=>{document.title=session?`${session.dealer.display_name||session.dealer.name||'Concessionaria'} · Dealer Cockpit`:'Dealer Cockpit'},[session]);useEffect(()=>{const handler=(e:KeyboardEvent)=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('global-search')?.focus()}};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler)},[]);if(!session)return <Login onLogin={setSessionState}/>;const vehicle=vehicleId?data.vehicles.find(v=>v.id===vehicleId):undefined;const editingVehicle=editingId?data.vehicles.find(v=>v.id===editingId):undefined;const openVehicle=(id:string)=>{setView('garage');setVehicleId(id)};const saved=async(v:Vehicle)=>{setNewVehicleOpen(false);setEditingId(null);setView('garage');setVehicleId(v.id);await load()};const dealerName=session.dealer.display_name||session.dealer.name||'Concessionaria';return <Shell view={view} onView={setView} profile={session.profile} dealerName={dealerName} onLogout={()=>{logout();setSessionState(null);setData(empty)}}>{error&&<div className="load-error">{error}<button onClick={()=>void load()}><RefreshCw/>Riprova</button></div>}{busy&&<div className="loading-bar"/>}{view==='today'&&<TodayPage data={data} onVehicle={openVehicle} onView={setView}/>} {view==='garage'&&<GaragePage data={data} onVehicle={setVehicleId} onCreate={()=>setNewVehicleOpen(true)} writable={canWriteGarage(session)}/>} {view==='clients'&&<ClientsPage data={data} writable={canWriteCustomers(session)} onRefresh={load}/>} {view==='calendar'&&<CalendarPage data={data} writable={canWriteCalendar(session)} onRefresh={load}/>} {view==='sales'&&<SalesPage data={data} session={session} onRefresh={load}/>} {view==='more'&&<MorePage/>}{vehicle&&<VehicleDrawer vehicle={vehicle} data={data} session={session} onClose={()=>setVehicleId(null)} onEdit={()=>setEditingId(vehicle.id)} onRefresh={load}/>} {(newVehicleOpen||editingVehicle)&&<VehicleFormModal vehicle={editingVehicle} onClose={()=>{setNewVehicleOpen(false);setEditingId(null)}} onSaved={v=>void saved(v)}/>}</Shell>}
