import type {ReactNode} from 'react'
import {CalendarDays,CarFront,ChevronDown,LayoutDashboard,LogOut,Menu,Search,ShoppingBag,UsersRound} from 'lucide-react'
import type {Profile,View} from '../types'
const nav:[View,string,typeof LayoutDashboard][]=[['today','Oggi',LayoutDashboard],['garage','Garage',CarFront],['clients','Clienti',UsersRound],['calendar','Calendario',CalendarDays],['sales','Vendite',ShoppingBag],['more','Altro',Menu]]
export function Shell({view,onView,profile,dealerName,onLogout,children}:{view:View;onView:(v:View)=>void;profile:Profile;dealerName:string;onLogout:()=>void;children:ReactNode}){return <div className="app-shell"><aside className="sidebar"><div className="brand"><div className="brand-icon"><CarFront/></div><div><b>{dealerName}</b><span>Dealer Cockpit</span></div></div><nav>{nav.map(([id,label,Icon])=><button key={id} className={view===id?'active':''} onClick={()=>onView(id)}><Icon/><span>{label}</span></button>)}</nav><div className="side-bottom"><small>Spazio concessionaria</small><button onClick={onLogout}><LogOut/>Esci</button></div></aside><main className="workspace"><header className="topbar"><button className="search-shell" onClick={()=>document.getElementById('global-search')?.focus()}><Search/><span>Cerca auto o cliente…</span><kbd>⌘K</kbd></button><div className="identity"><div className="avatar">{(profile.display_name||profile.username||'U').slice(0,1).toUpperCase()}</div><div><b>{profile.display_name||profile.username||'Utente'}</b><span>{profile.role}</span></div><ChevronDown size={15}/></div></header><div className="page">{children}</div></main><nav className="mobile-nav">{nav.map(([id,label,Icon])=><button key={id} className={view===id?'active':''} onClick={()=>onView(id)}><Icon/><small>{label}</small></button>)}</nav></div>}
