import {FormEvent,useState} from 'react'
import {Camera,CheckCircle2,CircleDollarSign,Image as ImageIcon,Pencil,Plus,Star,Trash2,Wrench,X} from 'lucide-react'
import {integer,money,vehicleName} from '../lib/format'
import {canSeeFinance,canWriteGarage,completeWorkItem,deleteVehiclePhoto,saveWorkItem,setVehicleCover,uploadVehiclePhotos} from '../lib/api'
import {PHOTO_TARGET,vehicleCompleteness} from '../domain/garage'
import {PrivateImage} from './PrivateImage'
import type {SessionPayload,TenantData,Vehicle} from '../types'

export function VehicleDrawer({vehicle,data,session,onClose,onEdit,onRefresh}:{vehicle:Vehicle;data:TenantData;session:SessionPayload;onClose:()=>void;onEdit:()=>void;onRefresh:()=>Promise<void>}){
  const media=data.media.filter(x=>x.vehicle_id===vehicle.id&&(x.kind||'PHOTO')==='PHOTO').sort((a,b)=>(a.sort_order||0)-(b.sort_order||0));const works=data.workItems.filter(x=>x.vehicle_id===vehicle.id&&!['DONE','CANCELLED'].includes(x.status||''));const financial=data.financials.find(x=>x.vehicle_id===vehicle.id);const costs=data.costs.filter(x=>x.vehicle_id===vehicle.id).reduce((s,x)=>s+Number(x.amount||0),0);const cover=media.find(x=>x.is_cover)||media[0];const writable=canWriteGarage(session);const completeness=vehicleCompleteness(vehicle,media.length)
  const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [workOpen,setWorkOpen]=useState(false)
  async function run(task:()=>Promise<unknown>){setBusy(true);setError('');try{await task();await onRefresh()}catch(err){setError(err instanceof Error?err.message:'Operazione non riuscita')}finally{setBusy(false)}}
  async function photos(files:FileList|null){if(!files?.length)return;await run(()=>uploadVehiclePhotos(vehicle,[...files],media))}
  async function removePhoto(id:string){const item=media.find(x=>x.id===id);if(!item||!window.confirm('Rimuovere questa foto dalla scheda auto?'))return;await run(()=>deleteVehiclePhoto(vehicle,item,media))}
  async function coverPhoto(id:string){const item=media.find(x=>x.id===id);if(!item)return;await run(()=>setVehicleCover(vehicle,item))}
  async function complete(id:string){const item=works.find(x=>x.id===id);if(!item)return;await run(()=>completeWorkItem(item))}
  async function addWork(e:FormEvent<HTMLFormElement>){e.preventDefault();const fd=new FormData(e.currentTarget);await run(()=>saveWorkItem(vehicle.id,{title:String(fd.get('title')||''),category:String(fd.get('category')||'PREPARAZIONE'),priority:String(fd.get('priority')||'NORMAL'),due_date:String(fd.get('due_date')||'')||null,note:String(fd.get('note')||'')||null}));setWorkOpen(false)}
  return <div className="drawer-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><aside className="drawer garage-drawer-v2"><header><div><p className="eyebrow">SCHEDA AUTO</p><h2>{vehicleName(vehicle)}</h2><span>{vehicle.plate||'Targa mancante'} · {vehicle.year||'Anno —'} · {integer(vehicle.mileage)} km</span></div><div className="drawer-head-actions">{writable&&<button className="icon-btn" onClick={onEdit} aria-label="Modifica auto"><Pencil/></button>}<button className="icon-btn" onClick={onClose} aria-label="Chiudi"><X/></button></div></header>{error&&<div className="drawer-error">{error}</div>}<div className="drawer-cover garage-cover">{cover?<PrivateImage objectKey={cover.object_key} alt={vehicleName(vehicle)} className="drawer-cover-image"/>:<div><ImageIcon/><b>Nessuna foto</b><span>Da iPhone puoi scattare e caricare direttamente qui.</span></div>}<div className="cover-actions">{writable&&<label className={`photo-upload ${busy?'disabled':''}`}><Camera/> {busy?'Caricamento…':media.length?'Aggiungi foto':'Scatta foto'}<input data-testid="vehicle-photo-input" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" capture="environment" multiple disabled={busy} onChange={e=>void photos(e.target.files)}/></label>}</div></div><section className="completeness-panel"><div><span>COMPLETEZZA SCHEDA</span><b>{completeness.percent}%</b></div><div className="completion-track"><i style={{width:`${completeness.percent}%`}}/></div>{completeness.missing.length?<p>Manca: {completeness.missing.join(' · ')}</p>:<p className="complete-copy">Scheda pronta per il flusso commerciale.</p>}</section><section className="drawer-grid"><article><span>STATO</span><b>{(vehicle.status||'—').replaceAll('_',' ')}</b></article><article><span>PREZZO CLIENTE</span><b>{vehicle.asking_price?money(vehicle.asking_price):'Da impostare'}</b></article><article><span>FOTO</span><b>{media.length}/{PHOTO_TARGET}</b></article><article><span>LAVORI APERTI</span><b>{works.length}</b></article></section><section className="drawer-section"><div className="drawer-section-head"><h3><Camera/> Foto veicolo</h3>{writable&&media.length>0&&<label className="text-action"><Plus/> Aggiungi<input type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" capture="environment" multiple hidden disabled={busy} onChange={e=>void photos(e.target.files)}/></label>}</div>{media.length?<div className="photo-gallery">{media.map(item=><article className={`photo-tile ${item.is_cover?'cover':''}`} key={item.id}><PrivateImage objectKey={item.object_key} alt={item.caption||vehicleName(vehicle)} className="photo-tile-img"/><div className="photo-tile-actions">{item.is_cover?<span><Star/> Copertina</span>:writable?<button onClick={()=>void coverPhoto(item.id)} disabled={busy}><Star/> Copertina</button>:<span/>}{writable&&<button className="danger-icon" onClick={()=>void removePhoto(item.id)} disabled={busy} aria-label="Elimina foto"><Trash2/></button>}</div></article>)}</div>:<p className="empty-state">Nessuna foto caricata.</p>}</section><section className="drawer-section"><div className="drawer-section-head"><h3><Wrench/> Preparazione</h3>{writable&&<button className="text-action" onClick={()=>setWorkOpen(v=>!v)}><Plus/> Lavoro</button>}</div>{workOpen&&<form className="work-form" onSubmit={addWork}><input name="title" required placeholder="es. Tagliando completo"/><div><select name="category" defaultValue="PREPARAZIONE"><option>PREPARAZIONE</option><option>MECCANICA</option><option>CARROZZERIA</option><option>GOMME</option><option>CONSEGNA</option><option>ALTRO</option></select><select name="priority" defaultValue="NORMAL"><option value="LOW">Bassa</option><option value="NORMAL">Normale</option><option value="HIGH">Alta</option></select><input name="due_date" type="date"/></div><textarea name="note" rows={2} placeholder="Nota opzionale"/><button className="primary" disabled={busy}>Aggiungi lavoro</button></form>}{works.length?works.map(w=><div className="line-item work-line" key={w.id}><div><b>{w.title||w.category||'Lavoro'}</b><span>{w.status||'TODO'} {w.due_date?`· ${w.due_date}`:''} {w.priority?`· ${w.priority}`:''}</span></div>{writable&&<button className="complete-work" onClick={()=>void complete(w.id)} disabled={busy}><CheckCircle2/> Fatto</button>}</div>):<p className="empty-state">Nessun lavoro aperto.</p>}</section>{canSeeFinance(session)&&<section className="drawer-section finance"><h3><CircleDollarSign/> Finanze protette</h3><div className="finance-grid"><div><span>ACQUISTO</span><b>{financial?.purchase_price?money(financial.purchase_price):'—'}</b></div><div><span>SPESE</span><b>{money(costs)}</b></div><div><span>PREZZO MINIMO</span><b>{financial?.minimum_price?money(financial.minimum_price):'—'}</b></div></div></section>}</aside></div>}
